17	package org.apache.dubbo.remoting.transport.netty4;
18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.Version;
21	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
22	import org.apache.dubbo.common.logger.LoggerFactory;
23	import org.apache.dubbo.remoting.ChannelHandler;
24	import org.apache.dubbo.remoting.exchange.Request;
25	
26	import io.netty.channel.Channel;
27	import io.netty.channel.ChannelDuplexHandler;
28	import io.netty.channel.ChannelHandlerContext;
29	import io.netty.channel.ChannelPromise;
30	import io.netty.handler.timeout.IdleStateEvent;
31	
32	import static org.apache.dubbo.common.constants.CommonConstants.HEARTBEAT_EVENT;
33	import static org.apache.dubbo.common.constants.LoggerCodeConstants.TRANSPORT_UNEXPECTED_EXCEPTION;
34	
35	@io.netty.channel.ChannelHandler.Sharable
36	public class NettyClientHandler extends ChannelDuplexHandler {
37	    private static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(NettyClientHandler.class);
38	
39	    private final URL url;
40	
41	    private final ChannelHandler handler;
42	
43	    public NettyClientHandler(URL url, ChannelHandler handler) {
44	        if (url == null) {
45	            throw new IllegalArgumentException("url == null");
46	        }
47	        if (handler == null) {
48	            throw new IllegalArgumentException("handler == null");
49	        }
50	        this.url = url;
51	        this.handler = handler;
52	    }
53	
54	    @Override
55	    public void channelActive(ChannelHandlerContext ctx) throws Exception {
56	        Channel ch = ctx.channel();
57	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
58	        handler.connected(channel);
59	
60	        if (logger.isInfoEnabled()) {
61	            logger.info(
62	                    "The connection {} of {} -> {} is established.",
63	                    ch,
64	                    channel.getLocalAddressKey(),
65	                    channel.getRemoteAddressKey());
66	        }
67	    }
68	
69	    @Override
70	    public void channelInactive(ChannelHandlerContext ctx) throws Exception {
71	        Channel ch = ctx.channel();
72	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
73	        try {
74	            handler.disconnected(channel);
75	        } finally {
76	            NettyChannel.removeChannel(ch);
77	        }
78	
79	        if (logger.isInfoEnabled()) {
80	            logger.info(
81	                    "The connection {} of {} -> {} is disconnected.",
82	                    ch,
83	                    channel.getLocalAddressKey(),
84	                    channel.getRemoteAddressKey());
85	        }
86	    }
87	
88	    @Override
89	    public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
90	        NettyChannel channel = NettyChannel.getOrAddChannel(ctx.channel(), url, handler);
91	        handler.received(channel, msg);
92	    }
93	
94	    @Override
95	    public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) throws Exception {
96	        super.write(ctx, msg, promise);
97	    }
98	
99	    @Override
100	    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
101	        // send heartbeat when read idle.
102	        if (evt instanceof IdleStateEvent) {
103	            try {
104	                NettyChannel channel = NettyChannel.getOrAddChannel(ctx.channel(), url, handler);
105	                if (logger.isDebugEnabled()) {
106	                    logger.debug("IdleStateEvent triggered, send heartbeat to channel " + channel);
107	                }
108	                Request req = new Request();
109	                req.setVersion(Version.getProtocolVersion());
110	                req.setTwoWay(true);
111	                req.setEvent(HEARTBEAT_EVENT);
112	                channel.send(req);
113	            } finally {
114	                NettyChannel.removeChannelIfDisconnected(ctx.channel());
115	            }
116	        } else {
117	            super.userEventTriggered(ctx, evt);
118	        }
119	    }
120	
121	    @Override
122	    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
123	        Channel ch = ctx.channel();
124	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
125	        try {
126	            handler.caught(channel, cause);
127	        } finally {
128	            NettyChannel.removeChannelIfDisconnected(ch);
129	        }
130	
131	        if (logger.isWarnEnabled()) {
132	            logger.warn(
133	                    TRANSPORT_UNEXPECTED_EXCEPTION,
134	                    "",
135	                    "",
136	                    channel == null
137	                            ? String.format("The connection %s has exception.", ch)
138	                            : String.format(
139	                                    "The connection %s of %s -> %s has exception.",
140	                                    ch, channel.getLocalAddressKey(), channel.getRemoteAddressKey()),
141	                    cause);
142	        }
143	    }
144	}
