17	package org.apache.dubbo.remoting.transport.netty4;
18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
21	import org.apache.dubbo.common.logger.LoggerFactory;
22	import org.apache.dubbo.common.utils.NetUtils;
23	import org.apache.dubbo.remoting.Channel;
24	import org.apache.dubbo.remoting.ChannelHandler;
25	import org.apache.dubbo.remoting.Constants;
26	
27	import javax.net.ssl.SSLSession;
28	
29	import java.util.Map;
30	import java.util.concurrent.ConcurrentHashMap;
31	
32	import io.netty.channel.ChannelDuplexHandler;
33	import io.netty.channel.ChannelHandlerContext;
34	import io.netty.channel.ChannelPromise;
35	import io.netty.handler.ssl.SslHandshakeCompletionEvent;
36	import io.netty.handler.timeout.IdleStateEvent;
37	import io.netty.util.AttributeKey;
38	
39	import static org.apache.dubbo.common.constants.LoggerCodeConstants.TRANSPORT_UNEXPECTED_EXCEPTION;
40	
41	/**
42	 * NettyServerHandler.
43	 */
44	@io.netty.channel.ChannelHandler.Sharable
45	public class NettyServerHandler extends ChannelDuplexHandler {
46	    private static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(NettyServerHandler.class);
47	    /**
48	     * the cache for alive worker channel.
49	     * <ip:port, dubbo channel>
50	     */
51	    private final Map<String, Channel> channels = new ConcurrentHashMap<>();
52	
53	    private static final AttributeKey<SSLSession> SSL_SESSION_KEY = AttributeKey.valueOf(Constants.SSL_SESSION_KEY);
54	
55	    private final URL url;
56	
57	    private final ChannelHandler handler;
58	
59	    public NettyServerHandler(URL url, ChannelHandler handler) {
60	        if (url == null) {
61	            throw new IllegalArgumentException("url == null");
62	        }
63	        if (handler == null) {
64	            throw new IllegalArgumentException("handler == null");
65	        }
66	        this.url = url;
67	        this.handler = handler;
68	    }
69	
70	    public Map<String, Channel> getChannels() {
71	        return channels;
72	    }
73	
74	    @Override
75	    public void channelActive(ChannelHandlerContext ctx) throws Exception {
76	        io.netty.channel.Channel ch = ctx.channel();
77	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
78	        if (channel != null) {
79	            channels.put(NetUtils.toAddressString(channel.getRemoteAddress()), channel);
80	        }
81	        handler.connected(channel);
82	
83	        if (logger.isInfoEnabled() && channel != null) {
84	            logger.info(
85	                    "The connection {} of {} -> {} is established.",
86	                    ch,
87	                    channel.getRemoteAddressKey(),
88	                    channel.getLocalAddressKey());
89	        }
90	    }
91	
92	    @Override
93	    public void channelInactive(ChannelHandlerContext ctx) throws Exception {
94	        io.netty.channel.Channel ch = ctx.channel();
95	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
96	        try {
97	            channels.remove(NetUtils.toAddressString(channel.getRemoteAddress()));
98	            handler.disconnected(channel);
99	        } finally {
100	            NettyChannel.removeChannel(ch);
101	        }
102	
103	        if (logger.isInfoEnabled()) {
104	            logger.info(
105	                    "The connection {} of {} -> {} is disconnected.",
106	                    ch,
107	                    channel.getRemoteAddressKey(),
108	                    channel.getLocalAddressKey());
109	        }
110	    }
111	
112	    @Override
113	    public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
114	        NettyChannel channel = NettyChannel.getOrAddChannel(ctx.channel(), url, handler);
115	        handler.received(channel, msg);
116	        // trigger qos handler
117	        ctx.fireChannelRead(msg);
118	    }
119	
120	    @Override
121	    public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) throws Exception {
122	        super.write(ctx, msg, promise);
123	        NettyChannel channel = NettyChannel.getOrAddChannel(ctx.channel(), url, handler);
124	        handler.sent(channel, msg);
125	    }
126	
127	    @Override
128	    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
129	        // server will close channel when server don't receive any heartbeat from client util timeout.
130	        if (evt instanceof IdleStateEvent) {
131	            NettyChannel channel = NettyChannel.getOrAddChannel(ctx.channel(), url, handler);
132	            try {
133	                logger.info("IdleStateEvent triggered, close channel " + channel);
134	                channel.close();
135	            } finally {
136	                NettyChannel.removeChannelIfDisconnected(ctx.channel());
137	            }
138	        }
139	        super.userEventTriggered(ctx, evt);
140	        if (evt instanceof SslHandshakeCompletionEvent) {
141	            SslHandshakeCompletionEvent handshakeEvent = (SslHandshakeCompletionEvent) evt;
142	            if (handshakeEvent.isSuccess()) {
143	                NettyChannel channel = NettyChannel.getOrAddChannel(ctx.channel(), url, handler);
144	                channel.setAttribute(
145	                        Constants.SSL_SESSION_KEY,
146	                        ctx.channel().attr(SSL_SESSION_KEY).get());
147	            }
148	        }
149	    }
150	
151	    @Override
152	    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
153	        io.netty.channel.Channel ch = ctx.channel();
154	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
155	        try {
156	            handler.caught(channel, cause);
157	        } finally {
158	            NettyChannel.removeChannelIfDisconnected(ch);
159	        }
160	
161	        if (logger.isWarnEnabled()) {
162	            logger.warn(
163	                    TRANSPORT_UNEXPECTED_EXCEPTION,
164	                    "",
165	                    "",
166	                    channel == null
167	                            ? String.format("The connection %s has exception.", ch)
168	                            : String.format(
169	                                    "The connection %s of %s -> %s has exception.",
170	                                    ch, channel.getRemoteAddressKey(), channel.getLocalAddressKey()),
171	                    cause);
172	        }
173	    }
174	}
