17	package org.apache.dubbo.remoting.transport.netty4.ssl;
18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
21	import org.apache.dubbo.common.logger.LoggerFactory;
22	import org.apache.dubbo.remoting.Constants;
23	
24	import javax.net.ssl.SSLEngine;
25	import javax.net.ssl.SSLSession;
26	
27	import io.netty.channel.ChannelHandlerContext;
28	import io.netty.channel.ChannelInboundHandlerAdapter;
29	import io.netty.handler.ssl.SslContext;
30	import io.netty.handler.ssl.SslHandler;
31	import io.netty.handler.ssl.SslHandshakeCompletionEvent;
32	import io.netty.util.AttributeKey;
33	
34	import static org.apache.dubbo.common.constants.LoggerCodeConstants.INTERNAL_ERROR;
35	
36	public class SslClientTlsHandler extends ChannelInboundHandlerAdapter {
37	
38	    private static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(SslClientTlsHandler.class);
39	    private static final AttributeKey<SSLSession> SSL_SESSION_KEY = AttributeKey.valueOf(Constants.SSL_SESSION_KEY);
40	    private final SslContext sslContext;
41	
42	    public SslClientTlsHandler(URL url) {
43	        this(SslContexts.buildClientSslContext(url));
44	    }
45	
46	    public SslClientTlsHandler(SslContext sslContext) {
47	        this.sslContext = sslContext;
48	    }
49	
50	    @Override
51	    public void handlerAdded(ChannelHandlerContext ctx) {
52	        SSLEngine sslEngine = sslContext.newEngine(ctx.alloc());
53	        ctx.pipeline().addAfter(ctx.name(), null, new SslHandler(sslEngine, false));
54	    }
55	
56	    @Override
57	    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
58	        if (evt instanceof SslHandshakeCompletionEvent) {
59	            SslHandshakeCompletionEvent handshakeEvent = (SslHandshakeCompletionEvent) evt;
60	            if (handshakeEvent.isSuccess()) {
61	                SSLSession session =
62	                        ctx.pipeline().get(SslHandler.class).engine().getSession();
63	                logger.info("TLS negotiation succeed with: " + session.getPeerHost());
64	                ctx.pipeline().remove(this);
65	                ctx.channel().attr(SSL_SESSION_KEY).set(session);
66	            } else {
67	                logger.error(
68	                        INTERNAL_ERROR,
69	                        "unknown error in remoting module",
70	                        "",
71	                        "TLS negotiation failed when connecting to remote server.",
72	                        handshakeEvent.cause());
73	                ctx.fireExceptionCaught(handshakeEvent.cause());
74	                ctx.close();
75	            }
76	        }
77	    }
78	}
