17	package org.apache.dubbo.remoting.transport.netty4.ssl;
18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
21	import org.apache.dubbo.common.logger.LoggerFactory;
22	import org.apache.dubbo.common.ssl.AuthPolicy;
23	import org.apache.dubbo.common.ssl.CertManager;
24	import org.apache.dubbo.common.ssl.ProviderCert;
25	import org.apache.dubbo.remoting.Constants;
26	
27	import javax.net.ssl.SSLSession;
28	
29	import java.util.List;
30	
31	import io.netty.buffer.ByteBuf;
32	import io.netty.channel.ChannelHandlerContext;
33	import io.netty.channel.ChannelPipeline;
34	import io.netty.handler.codec.ByteToMessageDecoder;
35	import io.netty.handler.ssl.SslContext;
36	import io.netty.handler.ssl.SslHandler;
37	import io.netty.handler.ssl.SslHandshakeCompletionEvent;
38	import io.netty.util.AttributeKey;
39	
40	import static org.apache.dubbo.common.constants.LoggerCodeConstants.INTERNAL_ERROR;
41	
42	public class SslServerTlsHandler extends ByteToMessageDecoder {
43	    private static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(SslServerTlsHandler.class);
44	
45	    private final URL url;
46	
47	    private final boolean sslDetected;
48	    private static final AttributeKey<SSLSession> SSL_SESSION_KEY = AttributeKey.valueOf(Constants.SSL_SESSION_KEY);
49	
50	    public SslServerTlsHandler(URL url) {
51	        this.url = url;
52	        this.sslDetected = false;
53	    }
54	
55	    public SslServerTlsHandler(URL url, boolean sslDetected) {
56	        this.url = url;
57	        this.sslDetected = sslDetected;
58	    }
59	
60	    @Override
61	    public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
62	        logger.error(
63	                INTERNAL_ERROR,
64	                "unknown error in remoting module",
65	                "",
66	                "TLS negotiation failed when trying to accept new connection.",
67	                cause);
68	        ctx.fireExceptionCaught(cause);
69	        ctx.close();
70	    }
71	
72	    @Override
73	    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
74	        if (evt instanceof SslHandshakeCompletionEvent) {
75	            SslHandshakeCompletionEvent handshakeEvent = (SslHandshakeCompletionEvent) evt;
76	            if (handshakeEvent.isSuccess()) {
77	                SSLSession session =
78	                        ctx.pipeline().get(SslHandler.class).engine().getSession();
79	                logger.info("TLS negotiation succeed with: " + session.getPeerHost());
80	                // Remove after handshake success.
81	                ctx.pipeline().remove(this);
82	                ctx.channel().attr(SSL_SESSION_KEY).set(session);
83	            } else {
84	                logger.error(
85	                        INTERNAL_ERROR,
86	                        "",
87	                        "",
88	                        "TLS negotiation failed when trying to accept new connection.",
89	                        handshakeEvent.cause());
90	                ctx.close();
91	            }
92	        }
93	        super.userEventTriggered(ctx, evt);
94	    }
95	
96	    @Override
97	    protected void decode(ChannelHandlerContext channelHandlerContext, ByteBuf byteBuf, List<Object> list)
98	            throws Exception {
99	        // Will use the first five bytes to detect a protocol.
100	        if (byteBuf.readableBytes() < 5) {
101	            return;
102	        }
103	
104	        if (sslDetected) {
105	            return;
106	        }
107	
108	        CertManager certManager =
109	                url.getOrDefaultFrameworkModel().getBeanFactory().getBean(CertManager.class);
110	        ProviderCert providerConnectionConfig = certManager.getProviderConnectionConfig(
111	                url, channelHandlerContext.channel().remoteAddress());
112	
113	        if (providerConnectionConfig == null) {
114	            channelHandlerContext.pipeline().remove(this);
115	            return;
116	        }
117	
118	        if (isSsl(byteBuf)) {
119	            SslContext sslContext = SslContexts.buildServerSslContext(providerConnectionConfig);
120	            enableSsl(channelHandlerContext, sslContext);
121	            return;
122	        }
123	
124	        if (providerConnectionConfig.getAuthPolicy() == AuthPolicy.NONE) {
125	            channelHandlerContext.pipeline().remove(this);
126	            return;
127	        }
128	
129	        logger.error(INTERNAL_ERROR, "", "", "TLS negotiation failed when trying to accept new connection.");
130	        channelHandlerContext.close();
131	    }
132	
133	    private boolean isSsl(ByteBuf buf) {
134	        return SslHandler.isEncrypted(buf);
135	    }
136	
137	    private void enableSsl(ChannelHandlerContext ctx, SslContext sslContext) {
138	        ChannelPipeline p = ctx.pipeline();
139	        ctx.pipeline().addAfter(ctx.name(), null, sslContext.newHandler(ctx.alloc()));
140	        p.addLast("unificationA", new SslServerTlsHandler(url, true));
141	        p.remove(this);
142	    }
143	}
