18	
19	import org.apache.dubbo.common.Parameters;
20	import org.apache.dubbo.common.URL;
21	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
22	import org.apache.dubbo.common.logger.LoggerFactory;
23	import org.apache.dubbo.common.utils.NetUtils;
24	import org.apache.dubbo.remoting.ChannelHandler;
25	import org.apache.dubbo.remoting.RemotingException;
26	import org.apache.dubbo.remoting.exchange.ExchangeClient;
27	import org.apache.dubbo.remoting.exchange.ExchangeHandler;
28	import org.apache.dubbo.remoting.exchange.Exchangers;
29	import org.apache.dubbo.rpc.RpcException;
30	
31	import java.net.InetSocketAddress;
32	import java.util.concurrent.CompletableFuture;
33	import java.util.concurrent.ExecutorService;
34	import java.util.concurrent.atomic.AtomicLong;
35	import java.util.concurrent.locks.Lock;
36	import java.util.concurrent.locks.ReentrantLock;
37	
38	import static org.apache.dubbo.common.constants.CommonConstants.LAZY_CONNECT_KEY;
39	import static org.apache.dubbo.common.constants.LoggerCodeConstants.PROTOCOL_FAILED_REQUEST;
40	import static org.apache.dubbo.remoting.Constants.SEND_RECONNECT_KEY;
41	import static org.apache.dubbo.rpc.protocol.dubbo.Constants.DEFAULT_LAZY_REQUEST_WITH_WARNING;
42	import static org.apache.dubbo.rpc.protocol.dubbo.Constants.LAZY_REQUEST_WITH_WARNING_KEY;
43	
44	/**
45	 * dubbo protocol support class.
46	 */
47	@SuppressWarnings("deprecation")
48	final class LazyConnectExchangeClient implements ExchangeClient {
49	
50	    private static final ErrorTypeAwareLogger logger =
51	            LoggerFactory.getErrorTypeAwareLogger(LazyConnectExchangeClient.class);
52	    private final boolean requestWithWarning;
53	    private final URL url;
54	    private final ExchangeHandler requestHandler;
55	    private final Lock connectLock = new ReentrantLock();
56	    private static final int warningPeriod = 5000;
57	    private final boolean needReconnect;
58	    private volatile ExchangeClient client;
59	    private final AtomicLong warningCount = new AtomicLong(0);
60	
61	    public LazyConnectExchangeClient(URL url, ExchangeHandler requestHandler) {
62	        // lazy connect, need set send.reconnect = true, to avoid channel bad status.
63	        this.url = url.addParameter(LAZY_CONNECT_KEY, true);
64	        this.needReconnect = url.getParameter(SEND_RECONNECT_KEY, false);
65	        this.requestHandler = requestHandler;
66	        this.requestWithWarning = url.getParameter(LAZY_REQUEST_WITH_WARNING_KEY, DEFAULT_LAZY_REQUEST_WITH_WARNING);
67	    }
68	
69	    private void initClient() throws RemotingException {
70	        if (client != null) {
71	            return;
72	        }
73	        if (logger.isInfoEnabled()) {
74	            logger.info("Lazy connect to " + url);
75	        }
76	        connectLock.lock();
77	        try {
78	            if (client != null) {
79	                return;
80	            }
81	            this.client = Exchangers.connect(url, requestHandler);
82	        } finally {
83	            connectLock.unlock();
84	        }
85	    }
86	
87	    @Override
88	    public CompletableFuture<Object> request(Object request) throws RemotingException {
89	        warning();
90	        checkClient();
91	        return client.request(request);
92	    }
93	
94	    @Override
95	    public URL getUrl() {
96	        return url;
97	    }
98	
99	    @Override
100	    public InetSocketAddress getRemoteAddress() {
101	        if (client == null) {
102	            return InetSocketAddress.createUnresolved(url.getHost(), url.getPort());
103	        } else {
104	            return client.getRemoteAddress();
105	        }
106	    }
107	
108	    @Override
109	    public CompletableFuture<Object> request(Object request, int timeout) throws RemotingException {
110	        warning();
111	        checkClient();
112	        return client.request(request, timeout);
113	    }
114	
115	    @Override
116	    public CompletableFuture<Object> request(Object request, ExecutorService executor) throws RemotingException {
117	        warning();
118	        checkClient();
119	        return client.request(request, executor);
120	    }
121	
122	    @Override
123	    public CompletableFuture<Object> request(Object request, int timeout, ExecutorService executor)
124	            throws RemotingException {
125	        warning();
126	        checkClient();
127	        return client.request(request, timeout, executor);
128	    }
129	
130	    /**
131	     * If {@link Constants.LAZY_REQUEST_WITH_WARNING_KEY} is configured, then warn once every 5000 invocations.
132	     */
133	    private void warning() {
134	        if (requestWithWarning) {
135	            if (warningCount.get() % warningPeriod == 0) {
136	                logger.warn(
137	                        PROTOCOL_FAILED_REQUEST,
138	                        "",
139	                        "",
140	                        url.getAddress() + " " + url.getServiceKey()
141	                                + " safe guard client , should not be called ,must have a bug.");
142	            }
143	            warningCount.incrementAndGet();
144	        }
145	    }
146	
147	    @Override
148	    public ChannelHandler getChannelHandler() {
149	        checkClient();
150	        return client.getChannelHandler();
151	    }
152	
153	    @Override
154	    public boolean isConnected() {
155	        if (client == null) {
156	            // Before the request arrives, LazyConnectExchangeClient always exists in a normal connection state
157	            // to prevent ReconnectTask from initiating a reconnection action.
158	            return true;
159	        } else {
160	            return client.isConnected();
161	        }
162	    }
163	
164	    @Override
165	    public InetSocketAddress getLocalAddress() {
166	        if (client == null) {
167	            return InetSocketAddress.createUnresolved(NetUtils.getLocalHost(), 0);
168	        } else {
169	            return client.getLocalAddress();
170	        }
171	    }
172	
173	    @Override
174	    public ExchangeHandler getExchangeHandler() {
175	        return requestHandler;
176	    }
177	
178	    @Override
179	    public void send(Object message) throws RemotingException {
180	        checkClient();
181	        client.send(message);
182	    }
