195	        }
196	
197	        // the order of judgment in the if statement cannot be changed.
198	        if (!(client instanceof LazyConnectExchangeClient)) {
199	            client = new LazyConnectExchangeClient(url, client.getExchangeHandler());
200	        }
201	    }
