18	
19	import org.apache.dubbo.common.config.ConfigurationUtils;
20	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
21	import org.apache.dubbo.common.logger.LoggerFactory;
22	import org.apache.dubbo.common.utils.CollectionUtils;
23	
24	import java.util.List;
25	import java.util.Objects;
26	
27	import static org.apache.dubbo.common.constants.LoggerCodeConstants.PROTOCOL_ERROR_CLOSE_CLIENT;
28	
29	public class SharedClientsProvider implements ClientsProvider {
30	    private static final ErrorTypeAwareLogger logger =
31	            LoggerFactory.getErrorTypeAwareLogger(SharedClientsProvider.class);
32	    private final DubboProtocol dubboProtocol;
33	    private final String addressKey;
34	    private final List<ReferenceCountExchangeClient> clients;
35	
36	    public SharedClientsProvider(
37	            DubboProtocol dubboProtocol, String addressKey, List<ReferenceCountExchangeClient> clients) {
38	        this.dubboProtocol = dubboProtocol;
39	        this.addressKey = addressKey;
40	        this.clients = clients;
41	    }
42	
43	    @Override
44	    public List<ReferenceCountExchangeClient> getClients() {
45	        return clients;
46	    }
47	
48	    public synchronized boolean increaseCount() {
49	        if (checkClientCanUse(clients)) {
50	            batchClientRefIncr(clients);
51	            return true;
52	        }
53	        return false;
54	    }
55	
56	    @Override
57	    public synchronized void close(int timeout) {
58	        for (ReferenceCountExchangeClient client : clients) {
59	            try {
60	                client.close(timeout);
61	            } catch (Throwable t) {
62	                logger.warn(PROTOCOL_ERROR_CLOSE_CLIENT, "", "", t.getMessage(), t);
63	            }
64	        }
65	        if (!checkClientCanUse(clients)) {
66	            dubboProtocol.scheduleRemoveSharedClient(addressKey, this);
67	        }
68	    }
69	
70	    public synchronized void forceClose() {
71	        for (ReferenceCountExchangeClient client : clients) {
72	            closeReferenceCountExchangeClient(client);
73	        }
74	    }
75	
76	    /**
77	     * Check if the client list is all available
78	     *
79	     * @param referenceCountExchangeClients
80	     * @return true-available，false-unavailable
81	     */
82	    private boolean checkClientCanUse(List<ReferenceCountExchangeClient> referenceCountExchangeClients) {
83	        if (CollectionUtils.isEmpty(referenceCountExchangeClients)) {
84	            return false;
85	        }
86	
87	        // As long as one client is not available, you need to replace the unavailable client with the available one.
88	        return referenceCountExchangeClients.stream()
89	                .noneMatch(referenceCountExchangeClient -> referenceCountExchangeClient == null
90	                        || referenceCountExchangeClient.getCount() <= 0
91	                        || referenceCountExchangeClient.isClosed());
92	    }
93	
94	    /**
95	     * Increase the reference Count if we create new invoker shares same connection, the connection will be closed without any reference.
96	     *
97	     * @param referenceCountExchangeClients
98	     */
99	    private void batchClientRefIncr(List<ReferenceCountExchangeClient> referenceCountExchangeClients) {
100	        if (CollectionUtils.isEmpty(referenceCountExchangeClients)) {
101	            return;
102	        }
103	        referenceCountExchangeClients.stream()
104	                .filter(Objects::nonNull)
105	                .forEach(ReferenceCountExchangeClient::incrementAndGetCount);
106	    }
107	
108	    /**
109	     * close ReferenceCountExchangeClient
110	     *
111	     * @param client
112	     */
113	    private void closeReferenceCountExchangeClient(ReferenceCountExchangeClient client) {
114	        if (client == null) {
115	            return;
116	        }
117	
118	        try {
119	            if (logger.isInfoEnabled()) {
120	                logger.info("Close dubbo connect: " + client.getLocalAddress() + "-->" + client.getRemoteAddress());
121	            }
122	
123	            client.close(ConfigurationUtils.reCalShutdownTime(client.getShutdownWaitTime()));
124	
125	            // TODO
126	            /*
127	             * At this time, ReferenceCountExchangeClient#client has been replaced with LazyConnectExchangeClient.
128	             * Do you need to call client.close again to ensure that LazyConnectExchangeClient is also closed?
129	             */
130	
131	        } catch (Throwable t) {
132	            logger.warn(PROTOCOL_ERROR_CLOSE_CLIENT, "", "", t.getMessage(), t);
133	        }
134	    }
135	}
