66	public class DecodeableRpcInvocation extends RpcInvocation implements Codec, Decodeable {
67	
68	    protected static final ErrorTypeAwareLogger log =
69	            LoggerFactory.getErrorTypeAwareLogger(DecodeableRpcInvocation.class);
70	
71	    protected final transient Channel channel;
72	
73	    protected final byte serializationType;
74	
75	    protected final transient InputStream inputStream;
76	
77	    protected final transient Request request;
78	
79	    protected volatile boolean hasDecoded;
80	
81	    protected final FrameworkModel frameworkModel;
82	
83	    protected final transient Supplier<CallbackServiceCodec> callbackServiceCodecFactory;
84	
85	    private static final boolean CHECK_SERIALIZATION =
86	            Boolean.parseBoolean(SystemPropertyConfigUtils.getSystemProperty(SERIALIZATION_SECURITY_CHECK_KEY, "true"));
87	
88	    public DecodeableRpcInvocation(
89	            FrameworkModel frameworkModel, Channel channel, Request request, InputStream is, byte id) {
90	        this.frameworkModel = frameworkModel;
91	        Assert.notNull(channel, "channel == null");
92	        Assert.notNull(request, "request == null");
93	        Assert.notNull(is, "inputStream == null");
94	        this.channel = channel;
95	        this.request = request;
96	        this.inputStream = is;
97	        this.serializationType = id;
98	        this.callbackServiceCodecFactory =
99	                CacheableSupplier.newSupplier(() -> new CallbackServiceCodec(frameworkModel));
100	    }
101	
102	    @Override
103	    public void decode() throws Exception {
104	        if (!hasDecoded && channel != null && inputStream != null) {
105	            try {
106	                decode(channel, inputStream);
107	            } catch (Throwable e) {
108	                if (log.isWarnEnabled()) {
109	                    log.warn(PROTOCOL_FAILED_DECODE, "", "", "Decode rpc invocation failed: " + e.getMessage(), e);
110	                }
111	                request.setBroken(true);
112	                request.setData(e);
113	            } finally {
114	                hasDecoded = true;
115	            }
116	        }
117	    }
118	
119	    @Override
120	    public void encode(Channel channel, OutputStream output, Object message) throws IOException {
121	        throw new UnsupportedOperationException();
122	    }
123	
124	    @Override
125	    public Object decode(Channel channel, InputStream input) throws IOException {
126	        int contentLength = input.available();
127	        getAttributes().put(Constants.CONTENT_LENGTH_KEY, contentLength);
128	        Object sslSession = channel.getAttribute(Constants.SSL_SESSION_KEY);
129	        if (null != sslSession) {
130	            put(Constants.SSL_SESSION_KEY, sslSession);
131	        }
132	
133	        ObjectInput in = CodecSupport.getSerialization(serializationType).deserialize(channel.getUrl(), input);
134	        this.put(SERIALIZATION_ID_KEY, serializationType);
135	
136	        String dubboVersion = in.readUTF();
137	        request.setVersion(dubboVersion);
138	        setAttachment(DUBBO_VERSION_KEY, dubboVersion);
139	
140	        String path = in.readUTF();
141	        setAttachment(PATH_KEY, path);
142	        String version = in.readUTF();
143	        setAttachment(VERSION_KEY, version);
144	
145	        // Do provider-level payload checks.
146	        String keyWithoutGroup = keyWithoutGroup(path, version);
147	        checkPayload(keyWithoutGroup);
148	
149	        setMethodName(in.readUTF());
150	
151	        String desc = in.readUTF();
152	        setParameterTypesDesc(desc);
153	
154	        ClassLoader originClassLoader = Thread.currentThread().getContextClassLoader();
155	        try {
156	            if (CHECK_SERIALIZATION) {
157	                PermittedSerializationKeeper keeper =
158	                        frameworkModel.getBeanFactory().getBean(PermittedSerializationKeeper.class);
159	                if (!keeper.checkSerializationPermitted(keyWithoutGroup, serializationType)) {
160	                    throw new IOException("Unexpected serialization id:" + serializationType
161	                            + " received from network, please check if the peer send the right id.");
162	                }
163	            }
164	            Object[] args = DubboCodec.EMPTY_OBJECT_ARRAY;
165	            Class<?>[] pts = DubboCodec.EMPTY_CLASS_ARRAY;
166	            if (desc.length() > 0) {
167	                pts = drawPts(path, version, desc, pts);
168	                if (pts == DubboCodec.EMPTY_CLASS_ARRAY) {
169	                    if (RpcUtils.isGenericCall(desc, getMethodName())) {
170	                        // Should recreate here for each invocation because the parameterTypes may be changed by user.
171	                        pts = new Class<?>[] {String.class, String[].class, Object[].class};
172	                    } else if (RpcUtils.isEcho(desc, getMethodName())) {
173	                        pts = new Class<?>[] {Object.class};
174	                    } else {
175	                        throw new IllegalArgumentException("Service not found:" + path + ", " + getMethodName());
176	                    }
177	                }
178	                args = drawArgs(in, pts);
179	            }
180	            setParameterTypes(pts);
181	
182	            Map<String, Object> map = in.readAttachments();
183	            if (CollectionUtils.isNotEmptyMap(map)) {
184	                addObjectAttachments(map);
185	            }
186	
187	            decodeArgument(channel, pts, args);
188	        } catch (ClassNotFoundException e) {
189	            throw new IOException(StringUtils.toString("Read invocation data failed.", e));
190	        } finally {
191	            Thread.currentThread().setContextClassLoader(originClassLoader);
192	            if (in instanceof Cleanable) {
193	                ((Cleanable) in).cleanup();
194	            }
195	        }
196	        return this;
197	    }
198	
199	    protected void decodeArgument(Channel channel, Class<?>[] pts, Object[] args) throws IOException {
200	        CallbackServiceCodec callbackServiceCodec = callbackServiceCodecFactory.get();
201	        for (int i = 0; i < args.length; i++) {
202	            args[i] = callbackServiceCodec.decodeInvocationArgument(channel, this, pts, i, args[i]);
203	        }
204	
205	        setArguments(args);
206	        String targetServiceName =
207	                buildKey(getAttachment(PATH_KEY), getAttachment(GROUP_KEY), getAttachment(VERSION_KEY));
208	        setTargetServiceUniqueName(targetServiceName);
209	    }
210	
211	    protected Class<?>[] drawPts(String path, String version, String desc, Class<?>[] pts) {
212	        FrameworkServiceRepository repository = frameworkModel.getServiceRepository();
213	        List<ProviderModel> providerModels =
214	                repository.lookupExportedServicesWithoutGroup(keyWithoutGroup(path, version));
215	        ServiceDescriptor serviceDescriptor = null;
216	        if (CollectionUtils.isNotEmpty(providerModels)) {
217	            for (ProviderModel providerModel : providerModels) {
218	                serviceDescriptor = providerModel.getServiceModel();
219	                if (serviceDescriptor != null) {
220	                    break;
221	                }
222	            }
223	        }
224	        if (serviceDescriptor == null) {
225	            // Unable to find ProviderModel from Exported Services
226	            for (ApplicationModel applicationModel : frameworkModel.getApplicationModels()) {
227	                for (ModuleModel moduleModel : applicationModel.getModuleModels()) {
228	                    serviceDescriptor = moduleModel.getServiceRepository().lookupService(path);
229	                    if (serviceDescriptor != null) {
230	                        break;
231	                    }
232	                }
233	            }
234	        }
235	
236	        if (serviceDescriptor != null) {
237	            MethodDescriptor methodDescriptor = serviceDescriptor.getMethod(getMethodName(), desc);
238	            if (methodDescriptor != null) {
239	                pts = methodDescriptor.getParameterClasses();
240	                this.setReturnTypes(methodDescriptor.getReturnTypes());
241	
242	                // switch TCCL
243	                if (CollectionUtils.isNotEmpty(providerModels)) {
244	                    if (providerModels.size() == 1) {
245	                        Thread.currentThread()
246	                                .setContextClassLoader(providerModels.get(0).getClassLoader());
247	                    } else {
248	                        // try all providerModels' classLoader can load pts, use the first one
249	                        for (ProviderModel providerModel : providerModels) {
250	                            ClassLoader classLoader = providerModel.getClassLoader();
251	                            boolean match = true;
252	                            for (Class<?> pt : pts) {
253	                                try {
254	                                    if (!pt.equals(classLoader.loadClass(pt.getName()))) {
255	                                        match = false;
256	                                    }
257	                                } catch (ClassNotFoundException e) {
258	                                    match = false;
259	                                }
260	                            }
261	                            if (match) {
262	                                Thread.currentThread().setContextClassLoader(classLoader);
263	                                break;
264	                            }
265	                        }
266	                    }
267	                }
268	            }
269	        }
270	        return pts;
271	    }
272	
273	    protected Object[] drawArgs(ObjectInput in, Class<?>[] pts) throws IOException, ClassNotFoundException {
274	        Object[] args;
275	        args = new Object[pts.length];
276	        for (int i = 0; i < args.length; i++) {
277	            args[i] = in.readObject(pts[i]);
278	        }
279	        return args;
280	    }
281	
282	    private void checkPayload(String serviceKey) throws IOException {
283	        ProviderModel providerModel =
284	                frameworkModel.getServiceRepository().lookupExportedServiceWithoutGroup(serviceKey);
285	        if (providerModel != null) {
286	            String payloadStr =
287	                    (String) providerModel.getServiceMetadata().getAttachments().get(PAYLOAD);
288	            if (payloadStr != null) {
289	                int payload = Integer.parseInt(payloadStr);
290	                if (payload <= 0) {
291	                    return;
292	                }
293	                if (request.getPayload() > payload) {
294	                    ExceedPayloadLimitException e = new ExceedPayloadLimitException("Data length too large: "
295	                            + request.getPayload() + ", max payload: " + payload + ", channel: " + channel);
296	                    log.error(TRANSPORT_EXCEED_PAYLOAD_LIMIT, "", "", e.getMessage(), e);
297	                    throw e;
298	                }
299	            }
300	        }
301	    }
302	
303	    protected void fillInvoker(DubboProtocol dubboProtocol) throws RemotingException {
304	        this.setInvoker(dubboProtocol.getInvoker(channel, this));
305	    }
306	}
